<script lang="ts">import Heading from '$lib/components/Heading.svelte';import Icon from '$lib/components/Icon.svelte';import Status from '$lib/components/Status.svelte';import ProjectMark from '$lib/components/ProjectMark.svelte';import {workspace} from '$lib/stores/workspace';import {primaryDomain} from '$lib/model';import {isWebsite} from '$lib/websites/model.js';let query='';$: sites=$workspace.projects.filter(p=>isWebsite(p.framework));$: rows=sites.filter(p=>[p.name,p.framework,primaryDomain($workspace.domains,p.id)?.name].join(' ').toLowerCase().includes(query.trim().toLowerCase()));</script>
<Heading title="Websites" subtitle="Install, migrate or manage your hosted websites."><a class="btn primary" href="/websites/new"><Icon name="Plus"/> New website</a></Heading><section class="card stack"><div class="toolbar"><label class="search"><Icon name="Search"/><input bind:value={query} placeholder="Search websites…" aria-label="Search websites"/></label><small>{rows.length} {rows.length===1?'website':'websites'}</small></div>{#each rows as p (p.id)}<div class="setting-row"><div class="row grow"><span class="project-tile-icon mark14"><ProjectMark framework={p.framework}/></span><div class="grow"><a class="link-btn native-path" href={'/projects/'+p.id+'/overview'}>{p.name}</a><small style="display:block">{primaryDomain($workspace.domains,p.id)?.name||'No address connected'} · {p.framework}</small></div></div><div class="row wrap"><Status value={p.status}/><a class="btn secondary small" href={'/projects/'+p.id+'/overview'}>Manage</a></div></div>{:else}<div class="empty-state"><span class="icon-box"><Icon name="Websites"/></span><h3>{sites.length?'No matching websites':'No websites yet'}</h3><p>{sites.length?'Try another name or domain.':'Install WordPress, migrate a backup or upload website files.'}</p><a class="btn primary" href="/websites/new">New website</a></div>{/each}</section><p class="subtitle native-note">Websites are also projects. Files, domains and database access share the same management views.</p>
